class Solution {
public:
    int lengthLongestPath(string input) {
        stringstream ss(input);
        string line;
        unordered_map<int, int> pathLen;
        pathLen[0] = 0;
        int maxLen = 0;
        while (getline(ss, line, '\n')) {
            int depth = 0;
            while (depth < static_cast<int>(line.size()) && line[depth] == '\t') depth++;
            string name = line.substr(depth);
            if (name.find('.') != string::npos) {
                maxLen = max(maxLen, pathLen[depth] + static_cast<int>(name.size()));
            } else {
                pathLen[depth + 1] = pathLen[depth] + static_cast<int>(name.size()) + 1;
            }
        }
        return maxLen;
    }
};

class Solution {
    public int lengthLongestPath(String input) {
        int maxLen = 0;
        Map<Integer, Integer> pathLen = new HashMap<>();
        pathLen.put(0, 0);
        for (String line : input.split("\n")) {
            int depth = 0;
            while (depth < line.length() && line.charAt(depth) == '\t') depth++;
            String name = line.substring(depth);
            if (name.contains(".")) {
                maxLen = Math.max(maxLen, pathLen.get(depth) + name.length());
            } else {
                pathLen.put(depth + 1, pathLen.get(depth) + name.length() + 1);
            }
        }
        return maxLen;
    }
}

