var lengthLongestPath = function(input) {
    let maxLen = 0;
    const pathLen = new Map([[0, 0]]);
    for (const line of input.split('\n')) {
        let depth = 0;
        while (depth < line.length && line[depth] === '\t') depth++;
        const name = line.slice(depth);
        if (name.includes('.')) {
            maxLen = Math.max(maxLen, pathLen.get(depth) + name.length);
        } else {
            pathLen.set(depth + 1, pathLen.get(depth) + name.length + 1);
        }
    }
    return maxLen;
};
